  <input id="massRadiusInput" type="range" min="0.2" max="1.6" step="0.05" value="0.5"
    oninput="document.getElementById('massRadiusVal').value=(+this.value).toFixed(2);update_massRadius(+this.value)">
</label>
<label><input id="escapeInput" type="checkbox" onchange="toggle_escape(this.checked)"> Tint escaping neutrons red</label>
<button onclick="trigger_chainReaction()">▶ Fire one neutron (watch the generations)</button>
<span style="font-size:10px;color:#555;line-height:1.4">Hover an arrow to see whether that neutron was captured or lost. Click a starburst for its own neutron tally, or click the disc for the surface-vs-volume idea.</span>
<!-- @FIGURE_UI_END -->
// @FIGURE_CODE_BEGIN
(function () {
  var draw = SVG().addTo(document.getElementById('container')).size('100%', '100%');
  var W = 960, H = 560;
  draw.viewbox(0, 0, W, H);

  var COL = {
    disc: '#8a8ed0',
    star: '#f7c948',
    halo: '#ffe08a',
    core: '#fffbe8',
    arrow: '#15161a',
    escape: '#b0392c',
    text: '#111214',
    muted: '#565b66',
    ok: '#1c7a3c',
    warn: '#b0392c',
    hot: '#c2760a'
  };
  var NU = 2.45;                 // mean neutrons released per fission (2 or 3)
  var state = { mode: 'both', mass: 0.5, highlight: false };
  var timers = [], animItems = [];

  /* ---------- seeded RNG ---------- */
  function mulberry32(a) {
    return function () {
      a |= 0; a = a + 0x6D2B79F5 | 0;
      var t = Math.imul(a ^ a >>> 15, 1 | a);
      t = t + Math.imul(t ^ t >>> 7, 61 | t) ^ t;
      return ((t ^ t >>> 14) >>> 0) / 4294967296;
    };
  }

  /* ---------- neutron non-leakage probability (Monte-Carlo, deterministic) ---------- */
  function capProb(rRel, lamRel) {
    var rng = mulberry32(20240607), N = 4000, hit = 0;
    for (var i = 0; i < N; i++) {
      var rr = rRel * Math.sqrt(rng()), th = rng() * 6.283185307;
      var x = rr * Math.cos(th), y = rr * Math.sin(th);
      var a = rng() * 6.283185307, d = -lamRel * Math.log(1 - 0.999999 * rng());
      var px = x + Math.cos(a) * d, py = y + Math.sin(a) * d;
      if (px * px + py * py < rRel * rRel) hit++;
    }
    return hit / N;
  }
  var LAMBDA_REL = (function () {
    var lo = 0.2, hi = 40, target = 1 / NU;
    for (var i = 0; i < 34; i++) {
      var mid = (lo + hi) / 2;
