// @FIGURE_CODE_BEGIN
(function () {
  var draw = SVG().addTo(document.getElementById('container')).size('100%', '100%');
  var W = 980, H = 620;
  draw.viewbox(0, 0, W, H);

  var COL = {
    disc: '#8b8fd0',
    arrow: '#111214',
    escape: '#b0392c',
    text: '#111214',
    muted: '#565b66',
    ok: '#1c7a3c',
    warn: '#b0392c',
    hot: '#c2760a'
  };
  var TAU = 6.283185307;
  var NU = 2.45;
  var state = { mode: 'both', mass: 0.5, highlight: false, touched: false };
  var timers = [], animItems = [];

  /* ---------- seeded RNG ---------- */
  function mulberry32(a) {
    return function () {
      a |= 0; a = a + 0x6D2B79F5 | 0;
      var t = Math.imul(a ^ a >>> 15, 1 | a);
      t = t + Math.imul(t ^ t >>> 7, 61 | t) ^ t;
      return ((t ^ t >>> 14) >>> 0) / 4294967296;
    };
  }

  /* ---------- non-leakage probability (deterministic Monte-Carlo) ---------- */
  function capProb(rRel, lamRel) {
    var rng = mulberry32(20240607), N = 3500, hit = 0;
    for (var i = 0; i < N; i++) {
      var rr = rRel * Math.sqrt(rng()), th = rng() * TAU;
      var x = rr * Math.cos(th), y = rr * Math.sin(th);
      var a = rng() * TAU, d = -lamRel * Math.log(1 - 0.999999 * rng());
      var px = x + Math.cos(a) * d, py = y + Math.sin(a) * d;
      if (px * px + py * py < rRel * rRel) hit++;
    }
    return hit / N;
  }
  var LAMBDA_REL = (function () {
    var lo = 0.2, hi = 40, target = 1 / NU;
    for (var i = 0; i < 32; i++) {
      var mid = (lo + hi) / 2;
      if (capProb(1, mid) > target) lo = mid; else hi = mid;
    }
    return (lo + hi) / 2;
  })();
  function physics(mass) {
    var P = capProb(Math.sqrt(mass), LAMBDA_REL);
    return { P: P, k: NU * P, leak: (1 - P) * 100 };
  }
  function statusOf(k) {
    if (k < 0.97) return { t: 'Sub-critical mass', c: COL.warn, m: 'chain dies out' };
    if (k <= 1.03) return { t: 'Critical mass', c: COL.ok, m: 'self-sustaining' };
    return { t: 'Super-critical mass', c: COL.hot, m: 'reaction grows' };
  }

  /* ---------- geometry helpers ---------- */
  function rayCircle(px, py, ux, uy, cx, cy, R) {
    var fx = px - cx, fy = py - cy;
    var b = fx * ux + fy * uy, c = fx * fx + fy * fy - R * R;
    var disc = b * b - c;
    if (disc < 0) return 0;
    return -b + Math.sqrt(disc);
  }
  function arrow(g, x1, y1, x2, y2, color, w) {
    var dx = x2 - x1, dy = y2 - y1, L = Math.sqrt(dx * dx + dy * dy);
    if (L < 10) return null;
    var ux = dx / L, uy = dy / L;
    var hl = w * 3.6, hw = w * 2.0;
    var bx = x2 - ux * hl, by = y2 - uy * hl;
    var grp = g.group();
    grp.line(x1, y1, bx + ux * 1.5, by + uy * 1.5)
      .stroke({ color: color, width: w, linecap: 'butt' });
    grp.polygon([[x2, y2], [bx - uy * hw, by + ux * hw], [bx + uy * hw, by - ux * hw]]).fill(color);
    return grp;
  }
  function starPoints(x, y, r, rot, spikes) {
    var pts = [], n = spikes * 2;
    for (var i = 0; i < n; i++) {
      var a = rot + i * Math.PI / spikes;
      var rr = (i % 2 === 0) ? r : r * 0.36;
      pts.push([x + Math.cos(a) * rr, y + Math.sin(a) * rr]);
    }
    return pts;
  }
  function halo(t) {
    t.attr({ 'paint-order': 'stroke', stroke: '#fff', 'stroke-width': 3.5, 'stroke-linejoin': 'round' });
    return t;
  }

  /* ---------- chain-reaction simulation ---------- */
  function simulate(cx, cy, R, lam, maxEv, seed, starR) {
    var rng = mulberry32(seed >>> 0);
    var minD = Math.max(2.5 * starR, 0.18 * R);
    var events = [{ x: cx - 0.34 * R, y: cy - 0.30 * R, gen: 0, nCap: 0, nEsc: 0, nOut: 0 }];
    var neutrons = [], queue = [0], guard = 0;
    while (queue.length && events.length < maxEv && guard++ < 400) {
      var ei = queue.shift(), e = events[ei];
      var n = (rng() < 0.45) ? 3 : 2;
      var base = rng() * TAU;
      for (var j = 0; j < n; j++) {
        var ang = base + j * TAU / n + (rng() - 0.5) * 0.9;
        var d = -lam * Math.log(1 - 0.999 * rng());
        var ca = Math.cos(ang), sa = Math.sin(ang);
        var lim = 0.90 * R;
        var px = e.x + ca * d, py = e.y + sa * d;
        var inside = ((px - cx) * (px - cx) + (py - cy) * (py - cy)) < lim * lim;
        e.nOut++;
        if (inside && d < minD) {
          d = minD + rng() * minD * 0.55;
          px = e.x + ca * d; py = e.y + sa * d;
          inside = ((px - cx) * (px - cx) + (py - cy) * (py - cy)) < lim * lim;
        }
        if (inside) {
          var ni = -1, nd = 1e9;
          for (var q = 0; q < events.length; q++) {
            if (q === ei) continue;
            var ddx = events[q].x - px, ddy = events[q].y - py;
            var dd = Math.sqrt(ddx * ddx + ddy * ddy);
            if (dd < nd) { nd = dd; ni = q; }
          }
          var tgt = null;
          if (ni >= 0 && nd < minD * 1.05) tgt = events[ni];
          else if (events.length < maxEv) {
            tgt = { x: px, y: py, gen: e.gen + 1, nCap: 0, nEsc: 0, nOut: 0 };
            events.push(tgt); queue.push(events.length - 1);
          } else if (ni >= 0 && nd < 0.8 * R) tgt = events[ni];
          neutrons.push({ from: e, to: tgt, ex: px, ey: py, captured: true, gen: e.gen });
          e.nCap++;
        } else {
          var t = rayCircle(e.x, e.y, ca, sa, cx, cy, R);
          neutrons.push({
            from: e, to: null,
            ex: e.x + ca * (t + 0.11 * R), ey: e.y + sa * (t + 0.11 * R),
            captured: false, gen: e.gen
          });
          e.nEsc++;
        }
      }
    }
    var esc = 0, cap = 0;
    for (var i = 0; i < neutrons.length; i++) { if (neutrons[i].captured) cap++; else esc++; }
    return { events: events, neutrons: neutrons, esc: esc, cap: cap };
  }
  function bestSim(cx, cy, R, lam, maxEv, seed0, starR) {
    var best = null, want = Math.max(3, Math.ceil(maxEv * 0.8));
    for (var s = 0; s < 40; s++) {
      var sim = simulate(cx, cy, R, lam, maxEv, seed0 + s * 97 + 1, starR);
      if (!best || sim.events.length > best.events.length) best = sim;
      if (sim.events.length >= want) return sim;
    }
    return best;
  }

  /* ---------- gradients ---------- */
  var G = {};
  function makeGradients() {
    G.sphere = draw.gradient('radial', function (add) {
      add.stop(0, '#f6f7e8'); add.stop(0.45, '#cbcfb2'); add.stop(1, '#868d6e');
    });
    G.halo = draw.gradient('radial', function (add) {
      add.stop(0, '#fff3c4').stop(0, '#fff3c4');
      add.stop(0.35, '#ffe08a');
      add.stop(1, '#ffd35c');
    });
    G.star = draw.gradient('radial', function (add) {
      add.stop(0, '#fffdf0');
      add.stop(0.42, '#ffd253');
      add.stop(1, '#f3a51d');
    });
  }

  function drawStar(g, x, y, R, rot, spikes) {
    var sg = g.group();
    var h = sg.circle(R * 2.75).center(x, y).fill(G.halo).opacity(0.55);
    h.attr('filter', null);
    sg.circle(R * 1.9).center(x, y).fill(G.halo).opacity(0.65);
    sg.polygon(starPoints(x, y, R, rot, spikes)).fill(G.star)
      .stroke({ color: '#eb9d12', width: 0.8, linejoin: 'round' });
    sg.circle(R * 0.62).center(x, y).fill('#fffdf2');
    return sg;
  }

  /* ---------- panel ---------- */
  function drawPanel(p) {
    var r = p.Rc * Math.sqrt(p.mass);
    var lam = LAMBDA_REL * p.Rc;
    var starR = 0.105 * p.Rc;
    var w = Math.max(3.2, 0.023 * p.Rc);
    var maxEv = Math.max(3, Math.min(26, Math.round(3 * p.mass + 17 * p.mass * p.mass)));
    var sim = bestSim(p.cx, p.cy, r, lam, maxEv, p.seed, starR);
    var ph = physics(p.mass);
    var st = statusOf(ph.k);
    var g = draw.group();

    /* disc */
    var disc = g.circle(2 * r).center(p.cx, p.cy).fill(COL.disc).css('cursor', 'pointer');
    disc.on('mousemove', function (e) {
      showTooltip('Fissile sphere, ' + p.mass.toFixed(2) + ' × critical mass — escape happens on the SURFACE (∝ r²), capture throughout the VOLUME (∝ r³). k ≈ ' + ph.k.toFixed(2) + '.', e);
    }).on('mouseleave', hideTooltip).on('click', function () {
      showPopup('Surface vs. volume',
        'Neutrons can only be lost by crossing the surface, which grows as r², while the nuclei that can absorb them fill the volume, which grows as r³. ' +
        'Enlarging the sphere therefore shrinks the leakage fraction, and at one particular size exactly one neutron per fission survives to cause the next one — the critical mass.');
    });
    if (p.active && state.touched) {
      g.circle(2 * r).center(p.cx, p.cy).fill('none')
        .stroke({ color: '#ffffff', width: 2.2, opacity: 0.7 })
        .attr('stroke-dasharray', '10,9');
    }

    /* incident neutron */
    var e0 = sim.events[0];
    var A = Math.PI * 1.215;
    var sx = p.cx + Math.cos(A) * (r + 60), sy = p.cy + Math.sin(A) * (r + 60);
    var dx = e0.x - sx, dy = e0.y - sy, L = Math.sqrt(dx * dx + dy * dy);
    var ux = dx / L, uy = dy / L;
    var inc = arrow(g, sx + ux * 18, sy + uy * 18, e0.x - ux * starR, e0.y - uy * starR, COL.arrow, w);
    if (inc) {
      inc.css('cursor', 'pointer')
        .on('mousemove', function (e) { showTooltip('Incident neutron — the single neutron that starts the chain.', e); })
        .on('mouseleave', hideTooltip);
      animItems.push({ node: inc, gen: -1 });
    }

    /* neutron arrows */
    sim.neutrons.forEach(function (nn) {
      var x1 = nn.from.x, y1 = nn.from.y;
      var x2 = nn.to ? nn.to.x : nn.ex, y2 = nn.to ? nn.to.y : nn.ey;
