      if (capProb(1, mid) > target) lo = mid; else hi = mid;
    }
    return (lo + hi) / 2;
  })();
  function physics(mass) {
    var P = capProb(Math.sqrt(mass), LAMBDA_REL);
    return { P: P, k: NU * P, leak: (1 - P) * 100 };
  }
  function statusOf(k) {
    if (k < 0.97) return { t: 'Sub-critical mass', c: COL.warn, m: 'chain dies out' };
    if (k <= 1.03) return { t: 'Critical mass', c: COL.ok, m: 'self-sustaining' };
    return { t: 'Super-critical mass', c: COL.hot, m: 'reaction grows' };
  }

  /* ---------- geometry helpers ---------- */
  function rayCircle(px, py, ux, uy, cx, cy, R) {
    var fx = px - cx, fy = py - cy;
    var b = fx * ux + fy * uy, c = fx * fx + fy * fy - R * R;
    var disc = b * b - c;
    if (disc < 0) return 0;
    return -b + Math.sqrt(disc);
  }
  function arrow(g, x1, y1, x2, y2, color, w) {
    var dx = x2 - x1, dy = y2 - y1, L = Math.sqrt(dx * dx + dy * dy);
    if (L < 10) return null;
    var ux = dx / L, uy = dy / L;
    var hl = w * 3.6, hw = w * 2.0;
    var bx = x2 - ux * hl, by = y2 - uy * hl;
    var grp = g.group();
    grp.line(x1, y1, bx + ux * 1.5, by + uy * 1.5)
      .stroke({ color: color, width: w, linecap: 'butt' });
    grp.polygon([[x2, y2], [bx - uy * hw, by + ux * hw], [bx + uy * hw, by - ux * hw]]).fill(color);
    return grp;
  }
  function starPoints(x, y, r, rot, spikes) {
    var pts = [], n = spikes * 2;
    for (var i = 0; i < n; i++) {
      var a = rot + i * Math.PI / spikes;
      var rr = (i % 2 === 0) ? r : r * 0.36;
      pts.push([x + Math.cos(a) * rr, y + Math.sin(a) * rr]);
    }
    return pts;
  }
  function halo(t) {
    t.attr({ 'paint-order': 'stroke', stroke: '#fff', 'stroke-width': 3.5, 'stroke-linejoin': 'round' });
    return t;
  }

  /* ---------- chain-reaction simulation ---------- */
  function simulate(cx, cy, R, lam, maxEv, seed, starR) {
    var rng = mulberry32(seed >>> 0);
    var minD = Math.max(2.5 * starR, 0.18 * R);
    var events = [{ x: cx - 0.34 * R, y: cy - 0.30 * R, gen: 0, nCap: 0, nEsc: 0, nOut: 0 }];
    var neutrons = [], queue = [0], guard = 0;
    while (queue.length && events.length < maxEv && guard++ < 400) {
      var ei = queue.shift(), e = events[ei];
      var n = (rng() < 0.45) ? 3 : 2;
      var base = rng() * TAU;
      for (var j = 0; j < n; j++) {
        var ang = base + j * TAU / n + (rng() - 0.5) * 0.9;
        var d = -lam * Math.log(1 - 0.999 * rng());
        var ca = Math.cos(ang), sa = Math.sin(ang);
        var lim = 0.90 * R;
        var px = e.x + ca * d, py = e.y + sa * d;
        var inside = ((px - cx) * (px - cx) + (py - cy) * (py - cy)) < lim * lim;
        e.nOut++;
        if (inside && d < minD) {
          d = minD + rng() * minD * 0.55;
          px = e.x + ca * d; py = e.y + sa * d;
          inside = ((px - cx) * (px - cx) + (py - cy) * (py - cy)) < lim * lim;
        }
        if (inside) {
          var ni = -1, nd = 1e9;
          for (var q = 0; q < events.length; q++) {
            if (q === ei) continue;
            var ddx = events[q].x - px, ddy = events[q].y - py;
            var dd = Math.sqrt(ddx * ddx + ddy * ddy);
            if (dd < nd) { nd = dd; ni = q; }
          }
          var tgt = null;
          if (ni >= 0 && nd < minD * 1.05) tgt = events[ni];
          else if (events.length < maxEv) {
            tgt = { x: px, y: py, gen: e.gen + 1, nCap: 0, nEsc: 0, nOut: 0 };
            events.push(tgt); queue.push(events.length - 1);
          } else if (ni >= 0 && nd < 0.8 * R) tgt = events[ni];
          neutrons.push({ from: e, to: tgt, ex: px, ey: py, captured: true, gen: e.gen });
          e.nCap++;
        } else {
          var t = rayCircle(e.x, e.y, ca, sa, cx, cy, R);
          neutrons.push({
            from: e, to: null,
            ex: e.x + ca * (t + 0.11 * R), ey: e.y + sa * (t + 0.11 * R),
            captured: false, gen: e.gen
          });
          e.nEsc++;
        }
      }
    }
    var esc = 0, cap = 0;
    for (var i = 0; i < neutrons.length; i++) { if (neutrons[i].captured) cap++; else esc++; }
    return { events: events, neutrons: neutrons, esc: esc, cap: cap };
  }
  function bestSim(cx, cy, R, lam, maxEv, seed0, starR) {
    var best = null, want = Math.max(3, Math.ceil(maxEv * 0.8));
    for (var s = 0; s < 40; s++) {
      var sim = simulate(cx, cy, R, lam, maxEv, seed0 + s * 97 + 1, starR);
      if (!best || sim.events.length > best.events.length) best = sim;
      if (sim.events.length >= want) return sim;
    }
    return best;
  }

  /* ---------- gradients ---------- */
  var G = {};
  function makeGradients() {
    G.sphere = draw.gradient('radial', function (add) {
      add.stop(0, '#f6f7e8'); add.stop(0.45, '#cbcfb2'); add.stop(1, '#868d6e');
    });
    G.halo = draw.gradient('radial', function (add) {
      add.stop(0, '#fff3c4').stop(0, '#fff3c4');
      add.stop(0.35, '#ffe08a');
      add.stop(1, '#ffd35c');
    });
    G.star = draw.gradient('radial', function (add) {
      add.stop(0, '#fffdf0');
      add.stop(0.42, '#ffd253');
      add.stop(1, '#f3a51d');
    });
  }

  function drawStar(g, x, y, R, rot, spikes) {
    var sg = g.group();
    var h = sg.circle(R * 2.75).center(x, y).fill(G.halo).opacity(0.55);
    h.attr('filter', null);
    sg.circle(R * 1.9).center(x, y).fill(G.halo).opacity(0.65);
    sg.polygon(starPoints(x, y, R, rot, spikes)).fill(G.star)
      .stroke({ color: '#eb9d12', width: 0.8, linejoin: 'round' });
    sg.circle(R * 0.62).center(x, y).fill('#fffdf2');
    return sg;
  }

  /* ---------- panel ---------- */
  function drawPanel(p) {
    var r = p.Rc * Math.sqrt(p.mass);
    var lam = LAMBDA_REL * p.Rc;
    var starR = 0.105 * p.Rc;
    var w = Math.max(3.2, 0.023 * p.Rc);
    var maxEv = Math.max(3, Math.min(26, Math.round(3 * p.mass + 17 * p.mass * p.mass)));
    var sim = bestSim(p.cx, p.cy, r, lam, maxEv, p.seed, starR);
    var ph = physics(p.mass);
    var st = statusOf(ph.k);
    var g = draw.group();

    /* disc */
    var disc = g.circle(2 * r).center(p.cx, p.cy).fill(COL.disc).css('cursor', 'pointer');
    disc.on('mousemove', function (e) {
      showTooltip('Fissile sphere, ' + p.mass.toFixed(2) + ' × critical mass — escape happens on the SURFACE (∝ r²), capture throughout the VOLUME (∝ r³). k ≈ ' + ph.k.toFixed(2) + '.', e);
    }).on('mouseleave', hideTooltip).on('click', function () {
      showPopup('Surface vs. volume',
        'Neutrons can only be lost by crossing the surface, which grows as r², while the nuclei that can absorb them fill the volume, which grows as r³. ' +
        'Enlarging the sphere therefore shrinks the leakage fraction, and at one particular size exactly one neutron per fission survives to cause the next one — the critical mass.');
    });
    if (p.active && state.touched) {
      g.circle(2 * r).center(p.cx, p.cy).fill('none')
        .stroke({ color: '#ffffff', width: 2.2, opacity: 0.7 })
        .attr('stroke-dasharray', '10,9');
    }

    /* incident neutron */
    var e0 = sim.events[0];
    var A = Math.PI * 1.215;
    var sx = p.cx + Math.cos(A) * (r + 60), sy = p.cy + Math.sin(A) * (r + 60);
    var dx = e0.x - sx, dy = e0.y - sy, L = Math.sqrt(dx * dx + dy * dy);
    var ux = dx / L, uy = dy / L;
    var inc = arrow(g, sx + ux * 18, sy + uy * 18, e0.x - ux * starR, e0.y - uy * starR, COL.arrow, w);
    if (inc) {
      inc.css('cursor', 'pointer')
        .on('mousemove', function (e) { showTooltip('Incident neutron — the single neutron that starts the chain.', e); })
        .on('mouseleave', hideTooltip);
      animItems.push({ node: inc, gen: -1 });
    }

    /* neutron arrows */
    sim.neutrons.forEach(function (nn) {
      var x1 = nn.from.x, y1 = nn.from.y;
      var x2 = nn.to ? nn.to.x : nn.ex, y2 = nn.to ? nn.to.y : nn.ey;
      var ddx = x2 - x1, ddy = y2 - y1, len = Math.sqrt(ddx * ddx + ddy * ddy);
      if (len < 2) return;
      var vx = ddx / len, vy = ddy / len;
      var ax = x1 + vx * (starR * 0.9), ay = y1 + vy * (starR * 0.9);
      var pad = nn.to ? starR * 0.95 : 0;
      var bx = x2 - vx * pad, by = y2 - vy * pad;
      if (Math.sqrt((bx - ax) * (bx - ax) + (by - ay) * (by - ay)) < 12) return;
      var col = (!nn.captured && state.highlight) ? COL.escape : COL.arrow;
      var a = arrow(g, ax, ay, bx, by, col, w);
      if (!a) return;
      a.css('cursor', 'pointer')
        .on('mousemove', function (e) {
          showTooltip(nn.captured
            ? 'Captured — this neutron struck another nucleus inside the mass and kept the chain going.'
            : 'Escaped — this neutron crossed the surface and is lost to the reaction.', e);
        })
        .on('mouseleave', hideTooltip)
        .on('click', function () {
          showPopup(nn.captured ? 'A productive neutron' : 'A lost neutron',
            nn.captured
              ? 'This neutron travelled less than its mean free path before meeting a nucleus, so it triggered a new fission. Captures like this are what make k large.'
              : 'This neutron reached the boundary before hitting a nucleus. Every escape reduces the multiplication factor k; in a small sphere most neutrons end this way.');
        });
      animItems.push({ node: a, gen: nn.gen, late: true });
    });

    /* starbursts (drawn on top of arrow tails) */
    sim.events.forEach(function (ev, idx) {
      var sg = drawStar(g, ev.x, ev.y, starR, (idx * 0.63) % 1.2, (idx % 2) ? 11 : 13);
      sg.css('cursor', 'pointer')
        .on('mousemove', function (e) {
          showTooltip('Fission event (generation ' + ev.gen + ') — ' +
            (ev.nOut ? ev.nOut + ' neutrons out: ' + ev.nCap + ' captured, ' + ev.nEsc + ' escaped'
              : 'its neutrons are not drawn'), e);
        })
        .on('mouseleave', hideTooltip)
        .on('click', function () {
          showPopup('Fission event, generation ' + ev.gen,
            ev.nOut
              ? 'This nucleus split and released ' + ev.nOut + ' neutrons: ' + ev.nCap + ' hit another nucleus and ' + ev.nEsc + ' escaped through the surface. ' +
              'No single fission "is" critical — k is the average number of productive neutrons over many events like this one.'
              : 'This fission sits at the edge of what the diagram draws, so its own neutrons are not shown. In a real mass the cascade simply continues from here.');
        });
      animItems.push({ node: sg, gen: ev.gen });
    });

    /* incident neutron sphere */
    var ball = g.group();
    ball.circle(26).center(sx, sy).fill(G.sphere).stroke({ color: '#6e7460', width: 1 });
    ball.circle(7).center(sx - 4, sy - 5).fill({ color: '#ffffff', opacity: 0.55 });

    /* titles & captions */
    halo(draw.text(p.fixedTitle || st.t)
      .font({ family: 'sans-serif', size: 22, weight: 'bold', anchor: 'middle' })
      .fill(COL.text).center(p.cx, 34));
    halo(draw.text(p.label).font({ family: 'sans-serif', size: 19, anchor: 'middle' })
      .fill(COL.text).center(p.cx, 508));

    return { sim: sim, ph: ph, st: st, mass: p.mass };
  }

  /* ---------- bottom readout + legend bar ---------- */
  function drawBottomBar(info) {
    var g = draw.group();
    var x = 24, y = 526, bw = W - 48, bh = 80;
    g.rect(bw, bh).move(x, y).radius(8).fill('#fbfbfd').stroke({ color: '#dcdfe6', width: 1 });

    g.text('Mass = ' + info.mass.toFixed(2) + ' × critical mass   ·   leakage ≈ ' +
      Math.round(info.ph.leak) + ' % of all neutrons   ·   arrows drawn: ' +
      info.sim.esc + ' escaped, ' + info.sim.cap + ' captured')
      .font({ family: 'sans-serif', size: 14 }).fill(COL.muted).move(x + 16, y + 10);

    g.text('k ≈ ' + info.ph.k.toFixed(2) + '  —  ' + info.st.m)
      .font({ family: 'sans-serif', size: 16, weight: 'bold', anchor: 'end' })
      .fill(info.st.c).move(x + bw - 16, y + 8);

    var ly = y + 56;
    g.circle(18).center(x + 30, ly).fill(G.sphere).stroke({ color: '#6e7460', width: 1 });
    g.text('incident neutron').font({ family: 'sans-serif', size: 13 }).fill(COL.muted).move(x + 46, ly - 9);
    drawStar(g, x + 208, ly, 12, 0.3, 12);
    g.text('fission event').font({ family: 'sans-serif', size: 13 }).fill(COL.muted).move(x + 226, ly - 9);
    arrow(g, x + 372, ly, x + 412, ly, COL.arrow, 3.6);
    g.text('captured → causes a new fission').font({ family: 'sans-serif', size: 13 }).fill(COL.muted).move(x + 420, ly - 9);
    arrow(g, x + 640, ly, x + 680, ly, COL.escape, 3.6);
    g.text('escaped through the surface').font({ family: 'sans-serif', size: 13 }).fill(COL.muted).move(x + 688, ly - 9);
  }

  /* ---------- render ---------- */
  function render() {
    clearTimers();
    draw.clear();
    animItems = [];
    makeGradients();
    var panels, infos;
    if (state.mode === 'both') {
      panels = [
        { cx: 262, cy: 290, Rc: 190, mass: state.mass, label: '(a)', active: true, seed: 11 },
        { cx: 702, cy: 290, Rc: 190, mass: 1.0, label: '(b)', active: false, seed: 73, fixedTitle: 'Critical mass' }
      ];
    } else {
      panels = [{
        cx: W / 2, cy: 285, Rc: 205, mass: state.mass,
        label: state.mode === 'a' ? '(a)' : '(b)', active: true,
        seed: state.mode === 'a' ? 11 : 73
      }];
    }
    infos = panels.map(drawPanel);
    if (state.touched || state.mode !== 'both') drawBottomBar(infos[0]);
  }

  /* ---------- animation ---------- */
  function clearTimers() { timers.forEach(clearTimeout); timers = []; }

  window.trigger_chainReaction = function () {
    clearTimers();
    animItems.forEach(function (it) { try { it.node.opacity(0); } catch (e) { } });
    animItems.forEach(function (it) {
      var d = (it.gen + 1) * 520 + (it.late ? 230 : 0);
      timers.push(setTimeout(function () {
        try { it.node.animate(320).opacity(1); } catch (e) { }
      }, d));
    });
  };

  /* ---------- controls ---------- */
  function setMassInput(m) {
    document.getElementById('massRadiusInput').value = m;
    document.getElementById('massRadiusVal').value = (+m).toFixed(2);
  }
  window.update_massRadius = function (v) { state.mass = +v; state.touched = true; render(); };
  window.toggle_escape = function (on) { state.highlight = !!on; state.touched = true; render(); };
  window.toggle_massMode = function (v) {
    state.mode = v;
    state.touched = true;
    if (v === 'a') { state.mass = 0.45; setMassInput(0.45); state.highlight = true; }
    else if (v === 'b') { state.mass = 1.15; setMassInput(1.15); state.highlight = true; }
    document.getElementById('escapeInput').checked = state.highlight;
    render();
  };

  /* ---------- demo steps ---------- */
  var steps = [
    {
      t: 'Two spheres, same material',
      n: 'Both discs are the same fissile material; only the amount differs. Gold starbursts are fission events and black arrows are the neutrons each one releases.',
      s: { mode: 'both', mass: 0.5, hl: false, touched: false }
    },
    {
      t: 'Sub-critical: the neutrons leak away',
      n: 'In the small sphere most arrows (red) cross the boundary and end outside — each fission produces fewer than one successful follow-up fission, so k is below 1 and the reaction dies out.',
      s: { mode: 'a', mass: 0.4, hl: true, touched: true }
    },
    {
      t: 'Grow the mass',
      n: 'Drag the mass up and watch the leakage readout fall: the surface grows as r² but the volume of nuclei able to absorb neutrons grows as r³, so bigger spheres keep a larger share of their own neutrons.',
      s: { mode: 'a', mass: 0.8, hl: true, touched: true }
    },
    {
      t: 'Critical mass reached',
      n: 'At k = 1 exactly one neutron per fission survives to cause another. The sphere is now large enough to sustain itself indefinitely.',
      s: { mode: 'b', mass: 1.0, hl: true, touched: true }
    },
    {
      t: 'Watch the cascade',
      n: 'Fire a single neutron into the critical sphere: one fission becomes 2, then 4, then 8, spreading across the mass while only a few neutrons escape at the rim.',
      s: { mode: 'b', mass: 1.1, hl: true, touched: true }, fire: true
    }
  ];
  var cur = 0;
  function applyStep(i) {
    cur = Math.max(0, Math.min(steps.length - 1, i));
    var st = steps[cur];
    state.mode = st.s.mode; state.mass = st.s.mass;
    state.highlight = st.s.hl; state.touched = st.s.touched;
    document.getElementById('massModeInput').value = st.s.mode;
    setMassInput(st.s.mass);
    document.getElementById('escapeInput').checked = st.s.hl;
    document.getElementById('demoNarration').textContent = st.t + ' — ' + st.n;
    document.getElementById('stepLabel').textContent = 'Step ' + (cur + 1) + ' / ' + steps.length;
    render();
    if (st.fire) timers.push(setTimeout(function () { window.trigger_chainReaction(); }, 380));
  }
  window.nextStep = function () { applyStep(cur + 1); };
  window.prevStep = function () { applyStep(cur - 1); };

  applyStep(0);
  window.__markRendered();
})();
// @FIGURE_CODE_END

